window.FIG_SERIES=window.FIG_SERIES||{};window.FIG_SERIES["FIG-736c27ca769f4401"]={"versions": [{"id": "FIG-736c27ca769f4401", "releases": ["R4.3.1"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">UML-Klassendiagramm zur Konfigurationsmetamodell-Spezifikation (ECUC Parameter Configuration) des Crypto Service Managers (CSM) innerhalb der AUTOSAR Classic Platform. Das Diagramm modelliert die Konfigurationsstruktur für asynchrone Callbacks (Benachrichtigungen über den Abschluss kryptografischer Operationen) an übergeordnete Software-Schichten (z. B. SW-Cs oder andere BSW-Module).</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<p class=\"fig-p\">Das Modell definiert vier Entitäten in hierarchischer Kompositionsbeziehung:</p>\n<ul class=\"fig-list\"><li><code>CsmCallbacks</code> (<code>EcucParamConfContainerDef</code>): Wurzel-Container mit Multiplizität [0..1].\n</li><li><code>CsmCallback</code> (<code>EcucParamConfContainerDef</code>): Untergeordneter Container (<code>+subContainer</code>), aggregiert über eine Komposition mit Multiplizität [0..\\*].\n</li><li><code>CsmCallbackFunc</code> (<code>EcucFunctionNameDef</code>): Parameter (<code>+parameter</code>), aggregiert durch <code>CsmCallback</code> mit Multiplizität [0..1], zur Spezifikation des Funktionsnamens der Callback-Routine.\n</li><li><code>CsmCallbackId</code> (<code>EcucIntegerParamDef</code>): Parameter (<code>+parameter</code>), aggregiert durch <code>CsmCallback</code> mit Multiplizität [0..1], Wertebereich <code>min = 0</code>, <code>max = 4294967295</code> (32-Bit Unsigned Integer), zur eindeutigen numerischen Identifikation des Callbacks.\n</li></ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Statisches Konfigurationsdiagramm ohne dynamische Laufzeitsequenzen oder Zustandsübergänge. Die Konfiguration steuert den Kontrollfluss zur Laufzeit, indem der CSM nach Abschluss einer asynchronen kryptografischen Anfrage die über <code>CsmCallbackFunc</code> konfigurierte Callback-Funktion aufruft, wobei <code>CsmCallbackId</code> zur Zuordnung dient.</p>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Normative Definition des Konfigurationsschemas für BSW-Generatoren und Werkzeuge. Beide Parameter innerhalb von <code>CsmCallback</code> besitzen die Multiplizität [0..1]; bei Aktivierung eines Callbacks muss ein valider C-Funktionsbezeichner (<code>EcucFunctionNameDef</code>) sowie eine ID (<code>uint32</code>) konfiguriert werden. Bei <code>lowerMultiplicity = 0</code> auf Container-Ebene ist die Callback-Konfiguration optional (z. B. in reinen Polling- oder synchronen Betriebsmodi).</p>", "model": "gemini-3.8-flash (via agy)"}, {"id": "FIG-93a34a24588b800b", "releases": ["R18-10_R4.4.0_R1.5.0"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">UML-Klassendiagramm zur Konfigurationsmetamodell-Spezifikation (ECUC Parameter Configuration) des Crypto Service Managers (CSM) innerhalb der AUTOSAR Classic Platform. Das Diagramm modelliert die Konfigurationsstruktur für asynchrone Callbacks (Benachrichtigungen über den Abschluss kryptografischer Operationen) an übergeordnete Software-Schichten (z. B. SW-Cs oder andere BSW-Module).</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<p class=\"fig-p\">Das Modell definiert vier Entitäten in hierarchischer Kompositionsbeziehung:</p>\n<ul class=\"fig-list\"><li><code>CsmCallbacks</code> (<code>EcucParamConfContainerDef</code>): Wurzel-Container mit Multiplizität [0..1].\n</li><li><code>CsmCallback</code> (<code>EcucParamConfContainerDef</code>): Untergeordneter Container (<code>+subContainer</code>), aggregiert über eine Komposition mit Multiplizität [0..\\*].\n</li><li><code>CsmCallbackFunc</code> (<code>EcucFunctionNameDef</code>): Parameter (<code>+parameter</code>), aggregiert durch <code>CsmCallback</code> mit Multiplizität [0..1], zur Spezifikation des Funktionsnamens der Callback-Routine.\n</li><li><code>CsmCallbackId</code> (<code>EcucIntegerParamDef</code>): Parameter (<code>+parameter</code>), aggregiert durch <code>CsmCallback</code> mit Multiplizität [0..1], Wertebereich <code>min = 0</code>, <code>max = 4294967295</code> (32-Bit Unsigned Integer), zur eindeutigen numerischen Identifikation des Callbacks.\n</li></ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Statisches Konfigurationsdiagramm ohne dynamische Laufzeitsequenzen oder Zustandsübergänge. Die Konfiguration steuert den Kontrollfluss zur Laufzeit, indem der CSM nach Abschluss einer asynchronen kryptografischen Anfrage die über <code>CsmCallbackFunc</code> konfigurierte Callback-Funktion aufruft, wobei <code>CsmCallbackId</code> zur Zuordnung dient.</p>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Normative Definition des Konfigurationsschemas für BSW-Generatoren und Werkzeuge. Beide Parameter innerhalb von <code>CsmCallback</code> besitzen die Multiplizität [0..1]; bei Aktivierung eines Callbacks muss ein valider C-Funktionsbezeichner (<code>EcucFunctionNameDef</code>) sowie eine ID (<code>uint32</code>) konfiguriert werden. Bei <code>lowerMultiplicity = 0</code> auf Container-Ebene ist die Callback-Konfiguration optional (z. B. in reinen Polling- oder synchronen Betriebsmodi).</p>", "model": "gemini-3.8-flash (via agy)"}], "trans": [{"from": "FIG-736c27ca769f4401", "to": "FIG-93a34a24588b800b", "fr": "R4.3.1", "tr": "R18-10_R4.4.0_R1.5.0", "change": "redaktionell", "label": "redaktionell", "html": "<ul class=\"fig-list\"><li>In allen Klassennamen (<code>CsmCallbacks</code>, <code>CsmCallback</code>, <code>CsmCallbackFunc</code>, <code>CsmCallbackId</code>) wurde das Leerzeichen vor dem Doppelpunkt zum Metatyp entfernt (z. B. <code>CsmCallbacks :EcucParamConfContainerDef</code> zu <code>CsmCallbacks: EcucParamConfContainerDef</code>).\n</li></ul>"}]};
